import{_ as a,o as r,c as d,a2 as e}from"./chunks/framework.CYjxsSA2.js";const p=JSON.parse('{"title":"空间测绘","description":"","frontmatter":{},"headers":[],"relativePath":"guide/spacemap.md","filePath":"guide/spacemap.md"}'),o={name:"guide/spacemap.md"};function n(s,t,l,i,h,c){return r(),d("div",null,[...t[0]||(t[0]=[e('<h1 id="空间测绘" tabindex="-1">空间测绘 <a class="header-anchor" href="#空间测绘" aria-label="Permalink to &quot;空间测绘&quot;">​</a></h1><p>空间测绘对接主流测绘平台，把外部资产数据一键拉入项目，与本地扫描结果交叉关联。</p><h2 id="支持的平台" tabindex="-1">支持的平台 <a class="header-anchor" href="#支持的平台" aria-label="Permalink to &quot;支持的平台&quot;">​</a></h2><table tabindex="0"><thead><tr><th>平台</th><th>说明</th></tr></thead><tbody><tr><td><strong>FOFA</strong></td><td>网络空间测绘搜索引擎</td></tr><tr><td><strong>Quake</strong></td><td>360 网络空间测绘</td></tr><tr><td><strong>Hunter</strong></td><td>鹰图平台</td></tr><tr><td><strong>Shodan</strong></td><td>全球联网设备搜索引擎</td></tr></tbody></table><p>API 凭据在<strong>系统配置 → 空间测绘</strong>中统一管理，支持配置多个平台，并查看各自的积分余额、会员等级等账户信息。</p><h2 id="查询模式" tabindex="-1">查询模式 <a class="header-anchor" href="#查询模式" aria-label="Permalink to &quot;查询模式&quot;">​</a></h2><table tabindex="0"><thead><tr><th>模式</th><th>行为</th></tr></thead><tbody><tr><td><strong>原生语法</strong></td><td>直接使用平台自己的查询语法</td></tr><tr><td><strong>域名模式</strong></td><td>输入域名，自动剥离协议与路径后查询</td></tr><tr><td><strong>IP 模式</strong></td><td>走 IP 专属语法</td></tr><tr><td><strong>自动判别</strong></td><td>自动判断输入是域名还是 IP 并选择语法</td></tr></tbody></table><p>域名 / IP 模式下查询内容不能为空。</p><h2 id="结果处理" tabindex="-1">结果处理 <a class="header-anchor" href="#结果处理" aria-label="Permalink to &quot;结果处理&quot;">​</a></h2><ul><li><strong>分页拉取</strong> —— 大结果集分批取回</li><li><strong>去重入库</strong> —— 与项目已有资产自动合并去重</li><li><strong>交叉关联</strong> —— 与<a href="/vaelor/guide/portscan.html">空间扫描</a>结果相互印证</li></ul><h2 id="常用参数" tabindex="-1">常用参数 <a class="header-anchor" href="#常用参数" aria-label="Permalink to &quot;常用参数&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参数</th><th>说明</th></tr></thead><tbody><tr><td>平台</td><td>一次任务选择一个平台</td></tr><tr><td>最大页数</td><td>分页拉取上限</td></tr><tr><td>每页条数</td><td>受各家 API 约束</td></tr><tr><td>全量模式</td><td>仅 FOFA：查询全量数据而非仅近一年</td></tr><tr><td>超时</td><td>单平台请求超时</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">FOFA 字段权限会自动降档</p><p>FOFA 按会员等级开放不同字段，低等级账号请求高等级字段会报「没有权限搜索 X 字段」，平台会自动降档重试，不必手工改语法。</p></div><h2 id="典型流程" tabindex="-1">典型流程 <a class="header-anchor" href="#典型流程" aria-label="Permalink to &quot;典型流程&quot;">​</a></h2><ol><li>在系统配置 → 空间测绘中填入平台 API Key</li><li>在项目<strong>空间测绘</strong>页选择平台与查询模式</li><li>输入目标或语法，执行查询</li><li>预览结果后选择入库，进入项目资产</li></ol>',15)])])}const b=a(o,[["render",n]]);export{p as __pageData,b as default};
